public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        StringTokenizer tz = new StringTokenizer(line);
        int n = Integer.parseInt(tz.nextToken());
        int m = Integer.parseInt(tz.nextToken());
        int[] g = new int[n];
        int[] s = new int[m];
        if (n > 0) {
            tz = new StringTokenizer(br.readLine());
            for(int i=0; i<n; i++) g[i] = Integer.parseInt(tz.nextToken());
        }
        if (m > 0) {
            tz = new StringTokenizer(br.readLine());
            for(int i=0; i<m; i++) s[i] = Integer.parseInt(tz.nextToken());
        }
